import{_ as d,o as e,c as o,a3 as r}from"./chunks/framework.CDBtBf5v.js";const h=JSON.parse('{"title":"OPC UA","description":"","frontmatter":{},"headers":[],"relativePath":"guide/protocols/opcua/index.md","filePath":"guide/protocols/opcua/index.md","lastUpdated":1794013948000}'),a={name:"guide/protocols/opcua/index.md"};function c(n,t,p,s,i,u){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="opc-ua" tabindex="-1">OPC UA <a class="header-anchor" href="#opc-ua" aria-label="Permalink to &quot;OPC UA&quot;">​</a></h1><p>OPC UA 模块支持 <strong>服务端（Server）</strong> 与 <strong>客户端（Client）</strong>，用于能源设备的地址空间建模、数据模拟、读写验证和实时订阅。协议实现基于 <code>asyncua 2.0.1</code>。</p><h2 id="连接与角色" tabindex="-1">连接与角色 <a class="header-anchor" href="#连接与角色" aria-label="Permalink to &quot;连接与角色&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>说明</th></tr></thead><tbody><tr><td>传输与端口</td><td>UA TCP，默认端口 <code>4840</code>，Endpoint URL 示例：<code>opc.tcp://127.0.0.1:4840/ems/</code></td></tr><tr><td>服务端</td><td>配置监听地址、端口、Endpoint 路径及命名空间 URI，维护变量并响应客户端请求</td></tr><tr><td>客户端</td><td>使用完整 Endpoint URL 连接，浏览远端地址空间，读取、写入和订阅变量</td></tr><tr><td>节点标识</td><td>使用 NodeId 定位节点，例如 <code>ns=2;s=ActivePower</code>；命名空间 URI 用于识别模型命名空间</td></tr><tr><td>数据质量</td><td>查看 StatusCode、源时间戳及服务器时间戳</td></tr></tbody></table><h2 id="功能模块" tabindex="-1">功能模块 <a class="header-anchor" href="#功能模块" aria-label="Permalink to &quot;功能模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>功能</th></tr></thead><tbody><tr><td>测点与地址空间</td><td>Excel 点表预检、导入与导出；变量定义、类型、初始值、可写权限；模型导入与导出</td></tr><tr><td>对象与变量值</td><td>树形浏览、属性与引用查看、实时值、写入与数值波形</td></tr><tr><td>数据模拟</td><td>固定值、随机、正弦波、步进；按变量配置参数及外部写入策略，运行时保存生效</td></tr><tr><td>客户端采集</td><td>单点读写、实时订阅、监控项采样间隔、队列、死区和自动重连</td></tr><tr><td>历史数据</td><td>服务端 SQLite 历史存储，客户端 HistoryRead 查询、分页和时间范围筛选</td></tr><tr><td>事件</td><td>服务端生成测试事件；客户端订阅事件源、筛选和 CSV 导出</td></tr><tr><td>MQTT/JSON 发布</td><td>服务端变量与事件 DataSetWriter、WriterGroup、主题、元数据和完整帧配置</td></tr><tr><td>安全配置</td><td>Endpoint 发现、应用证书、对端证书信任、消息安全模式和用户角色</td></tr><tr><td>运行与诊断</td><td>服务运行状态、会话、真实服务调用摘要、耗时与状态码</td></tr></tbody></table><blockquote><p>📷 <strong>截图待补：OPC UA 地址空间与变量定义</strong> — 展示 NodeId、BrowseName、数据类型、初始值及可写权限。 建议文件名：<code>opcua-address-space.png</code></p></blockquote><h2 id="发布订阅范围" tabindex="-1">发布订阅范围 <a class="header-anchor" href="#发布订阅范围" aria-label="Permalink to &quot;发布订阅范围&quot;">​</a></h2><p>客户端实时订阅使用原生 OPC UA Subscription；服务端 MQTT/JSON 发布需要额外连接 MQTT Broker。支持 MQTT 3.1.1、匿名 Broker、QoS 0 和 <code>mqtt://</code> / <code>mqtts://</code>，当前不提供 UADP 或 MQTT DataSetReader。历史数据通过 OPC UA 查询。</p><p>内置服务端提供原始历史读取；客户端聚合查询需要远端支持 ReadProcessed。配置与限制详见 <a href="./../../../OPCUA_PUBSUB.html">发布订阅工作区</a>。</p><h2 id="截图补充方式" tabindex="-1">截图补充方式 <a class="header-anchor" href="#截图补充方式" aria-label="Permalink to &quot;截图补充方式&quot;">​</a></h2><p>截图占位提供了建议文件名与已注释的图片语法。将图片放到 <code>resources/img/</code>（仓库 README）和 <code>docs/public/img/</code>（在线文档），然后取消对应图片语法的 HTML 注释并删除占位说明。同一张图在两个目录使用相同文件名。</p><table tabindex="0"><thead><tr><th>建议文件名</th><th>截图页面</th></tr></thead><tbody><tr><td><code>opcua-runtime.png</code></td><td>端点与运行状态</td></tr><tr><td><code>opcua-address-space.png</code></td><td>地址空间与变量定义</td></tr><tr><td><code>opcua-values.png</code></td><td>对象与实时变量值</td></tr><tr><td><code>opcua-simulation.png</code></td><td>模拟规则</td></tr><tr><td><code>opcua-client.png</code></td><td>客户端浏览与读写</td></tr><tr><td><code>opcua-subscription.png</code></td><td>客户端实时订阅</td></tr><tr><td><code>opcua-history.png</code></td><td>历史数据查询</td></tr><tr><td><code>opcua-events.png</code></td><td>事件订阅</td></tr><tr><td><code>opcua-pubsub.png</code></td><td>MQTT/JSON 发布器设置</td></tr><tr><td><code>opcua-security.png</code></td><td>证书与安全</td></tr><tr><td><code>opcua-diagnostics.png</code></td><td>会话与通信日志</td></tr></tbody></table><h2 id="界面预览" tabindex="-1">界面预览 <a class="header-anchor" href="#界面预览" aria-label="Permalink to &quot;界面预览&quot;">​</a></h2><blockquote><p>📷 <strong>截图待补：OPC UA 对象与实时变量值</strong> — 展开对象树并选择变量，展示属性、当前值、质量码、时间戳及波形。 建议文件名：<code>opcua-values.png</code></p></blockquote><blockquote><p>📷 <strong>截图待补：OPC UA 客户端实时订阅</strong> — 展示地址空间树、监控变量、发布与采样间隔，以及实时表格或趋势。 建议文件名：<code>opcua-subscription.png</code></p></blockquote><p>详细步骤见 <a href="./operation.html">操作指南</a>，通信排查见 <a href="./packet-view.html">报文与诊断查看</a>。</p>',17)])])}const b=d(a,[["render",c]]);export{h as __pageData,b as default};
